module alu (
    input [3:0] A,
    input [3:0] B,
    input [2:0] op,
    output [3:0] Z
);

    reg [3:0] temp;

    always @(*) begin
        case (op)
            3'b000: temp = A + B;
            3'b001: temp = A - B;
            3'b010: temp = A & B;
            3'b011: temp = A | B;
            3'b100: temp = A ^ B;
            3'b101: temp = ~A;
            default: temp = 4'b0;
        endcase
    end

    assign Z = temp;

endmodule

