    input clk,
    input LOAD,
    input SHIFT,
    input [7:0] DATA_IN,
    output reg [3:0] Q_OUT,
    output reg [3:0] Q_BAR_OUT
);

    always @(posedge clk) begin
        if (LOAD) begin
            Q_OUT <= DATA_IN[3:0];
            Q_BAR_OUT <= ~DATA_IN[3:0];
        end else if (SHIFT) begin
            Q_OUT <= {Q_OUT[2:0], 1'b0};
            Q_BAR_OUT <= {Q_BAR_OUT[2:0], 1'b1};
        end
    end

