    input [2:0] op,
    input clk,
    input reset,
    output reg [3:0] Z
);

    wire [3:0] alu_out;
    wire [3:0] shift_out;
    wire [3:0] and_out;

    alu alu_inst (
        .A(A),
        .B(B),
        .op(op),
        .Z(alu_out)
    );

    shift_register shift_inst (
        .clk(clk),
        .LOAD(LOAD),
        .SHIFT(SHIFT),
        .DATA_IN(DATA_IN),
        .Q_OUT(shift_out),
        .Q_BAR_OUT()
    );

    assign and_out = alu_out & shift_out;

    always @(posedge clk) begin
        if (reset) begin
            Z <= 4'b0;
        end else begin
            Z <= and_out;
        end
    end

endmodule

