	pciadrLD_i, adrcfg_o, adrmem_o, adr_o, cmd_o);

   	input clk_i;
   	input nrst_i;
	input [31:0] ad_i;
	input [3:0] cbe_i;
	input idsel_i;
	input [31:25] bar0_i;
	input memEN_i;
	input pciadrLD_i;
	output adrcfg_o;
	output adrmem_o;
	output [24:1] adr_o;
	output [3:0] cmd_o;

