    full_adder fa2(.A(A[1]), .B(B[1]), .CIN(carry_out_1), .S(sum[1]), .COUT(carry_out_2));
    full_adder fa3(.A(A[2]), .B(B[2]), .CIN(carry_out_2), .S(sum[2]), .COUT(COUT));
    full_adder fa4(.A(A[3]), .B(B[3]), .CIN(COUT), .S(sum[3]), .COUT());

    assign S = sum;

