assign mux_out01=c00sum00[1]?c11sum11:c10sum10,
       mux_out02=c01sum01[1]?c11sum11:c10sum10,
		 mux_out03=c20sum20[1]?c31sum31:c30sum30,
		 mux_out04=c21sum21[1]?c31sum31:c30sum30;

