    always @ (shifted) begin
        one_count = 0;
        for (i = 0; i < 4; i = i + 1) begin
            if (shifted[i] == 1) begin
                one_count = one_count + 1;
            end
        end
    end

    // Output
    always @ (one_count, shifted) begin
        out = one_count + shifted;
    end

