module barrel_shifter (
    input wire [3:0] in,
    input wire [2:0] vec,
    output wire [3:0] out,
    output wire o0,
    output wire o1,
    output wire o2 );

    wire [3:0] shift_1, shift_2, shift_3;

    assign shift_1 = {in[2:0], 1'b0};
    assign shift_2 = {in[1:0], 2'b00};
    assign shift_3 = {1'b0, in[0], 2'b00};

    assign out = (vec == 3'b000) ? in :
                 (vec == 3'b001) ? shift_1 :
                 (vec == 3'b010) ? shift_2 :
                 (vec == 3'b011) ? shift_3 :
                 4'b0000;

    assign o0 = in[0];
    assign o1 = in[1];
    assign o2 = in[2];

endmodule

