traffic_light_controller_cc78d538.rtl_code:
module traffic_light_controller(
  input reset,
  input clk,
  output reg green,
  output reg yellow,
  output reg red
);

  // Define the state machine states
  parameter green_state = 2'b00;
  parameter yellow_state = 2'b01;
  parameter red_state = 2'b10;

  // Define the state machine signals
  reg [1:0] state;
  reg [5:0] counter;

  // Initialize the state machine
  always @ (posedge clk, posedge reset) begin
    if (reset) begin
      state <= green_state;
      counter <= 0;
    end else begin
      case (state)
        green_state: begin
          counter <= counter + 1;
          if (counter == 30) begin
            state <= yellow_state;
            counter <= 0;
          end
        end
        yellow_state: begin
          counter <= counter + 1;
          if (counter == 5) begin
            state <= red_state;
            counter <= 0;
          end
        end
        red_state: begin
          counter <= counter + 1;
          if (counter == 25) begin
            state <= green_state;
            counter <= 0;
          end
        end
      endcase
    end
  end

  // Set the output signals based on the current state
  always @ (state) begin
    case (state)
      green_state: begin
        green <= 1;
        yellow <= 0;
        red <= 0;
      end
      yellow_state: begin
        green <= 0;
        yellow <= 1;
        red <= 0;
      end
      red_state: begin
        green <= 0;
        yellow <= 0;
        red <= 1;
      end
    endcase
  end

endmodule

if_stage_92cf8974.rtl_code:
module if_stage(
    input clk, rst, if_id_write_en, pc_write,
    input [1:0] pc_source,
    input pstop_i,
    output i_read_en,
    output [31:0] i_addr,
    input [31:0] i_instr_in, jump_addr, branch_addr, reg_data_1,
    output reg [31:0] IF_ID_next_i_addr,
    output reg [31:0] IF_ID_instruction
);

    reg [31:0] pc_reg, pc_next;
    wire [31:0] next_i_addr;
    wire mem_op = (IF_ID_instruction[31:26] == 6'b100011) || (IF_ID_instruction[31:26] == 6'b101011);

    assign next_i_addr = pc_reg + 4;
    assign i_read_en = 1;
    assign i_addr = pc_reg >> 2;

    always @* begin
        pc_next = pc_reg;

        case (pc_source)
            2'b00: pc_next = next_i_addr;
            2'b01: pc_next = branch_addr;
            2'b10: pc_next = jump_addr;
            2'b11: pc_next = reg_data_1;
        endcase
    end

    always @(posedge clk) begin
        if (rst) begin
            pc_reg <= 0;
        end else begin
            if (pc_write && !(pstop_i || mem_op)) begin
                pc_reg <= pc_next;
            end
        end
    end

    always @(posedge clk) begin
        if (rst) begin
            IF_ID_next_i_addr <= 0;
            IF_ID_instruction <= 0;
        end else begin
            if (if_id_write_en) begin
                IF_ID_next_i_addr <= next_i_addr;
                IF_ID_instruction <= !(pstop_i || mem_op) ? i_instr_in : 0;
            end
        end
    end

endmodule

