module carry_lookahead_adder (
    input [7:0] a,
    input [7:0] b,
    output [7:0] s,
    output overflow
);

wire [7:0] g;
wire [7:0] p;
wire [8:0] c;

assign g = a & b;
assign p = a ^ b;
assign c[0] = 1'b0;

genvar i;
generate
    for (i = 0; i < 8; i = i + 1) begin
        assign c[i+1] = g[i] | (p[i] & c[i]);
        assign s[i] = p[i] ^ c[i];
    end
endgenerate

assign overflow = ((a[7] == b[7]) && (a[7] != s[7]));

endmodule

