module booth_multiplier (
    input clk,
    input reset,
    input [3:0] a,
    input [3:0] b,
    input [1:0] booth_input,
    output reg [7:0] product
);

reg [7:0] register_a;
reg [7:0] register_b;
reg [7:0] register_p;

always @(posedge clk) begin
    if (reset) begin
        register_a <= 8'b0;
        register_b <= 8'b0;
        register_p <= 8'b0;
    end else begin
        register_a <= {a, 4'b0};
        register_b <= b;

        case (booth_input)
            2'b00: begin
                register_p <= register_p + register_b;
            end
            2'b01: begin
                register_p <= register_p - register_b;
            end
            2'b10: begin
                register_p <= register_p + register_b;
            end
            2'b11: begin
                register_p <= register_p - register_b;
            end
        endcase

        register_a <= register_a >> 1;
    end
end

always @(*) begin
    product <= register_p;
end

endmodule

